import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts before it is full.

    Creates a queue.Queue holding at most `cap` integers and tries to put each
    element of xs in order without blocking (put_nowait). Nothing is ever taken
    from the queue. The first put that fails because the queue is full stops
    the process, and the number of puts accepted up to that point is returned.

    A capacity of zero or less means the queue can hold nothing, so 0 is
    returned (it is not treated as unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_more_items_than_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4, 5]) == 2


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_capacity_one() -> None:
    assert accepted(1, [10, 20, 30]) == 1


def test_duplicates_are_all_counted() -> None:
    assert accepted(10, [1, 1, 1, 1]) == 4
    assert accepted(2, [1, 1, 1, 1]) == 2


@pytest.mark.parametrize("cap", [0, -1, -100])
def test_non_positive_capacity_accepts_nothing(cap: int) -> None:
    assert accepted(cap, [1, 2, 3]) == 0


@pytest.mark.parametrize(
    ("cap", "n"),
    [(0, 0), (1, 5), (3, 3), (4, 10), (100, 50)],
)
def test_result_is_min_of_capacity_and_length(cap: int, n: int) -> None:
    xs = list(range(n))
    assert accepted(cap, xs) == min(cap, n)


def test_input_not_modified() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]
